def parse_sku(code: str) -> dict:
    code = code.strip()
    parts = code.split('-')

    if len(parts) not in (3, 4):
        raise ValueError(f"Invalid SKU format: {code!r}")

    if parts[0] != 'HH':
        raise ValueError(f"Invalid SKU prefix: {parts[0]!r}")

    category = parts[1]
    if len(category) != 3 or not all('A' <= c <= 'Z' for c in category):
        raise ValueError(f"Invalid category: {category!r}")

    number = parts[2]
    if len(number) != 5 or not all('0' <= c <= '9' for c in number):
        raise ValueError(f"Invalid number: {number!r}")

    size = None
    if len(parts) == 4:
        size = parts[3]
        if size not in ('S', 'M', 'L', 'XL'):
            raise ValueError(f"Invalid size: {size!r}")

    return {"category": category, "number": number, "size": size}
